public class Main {
    static int shared = 0;

    public static void main(String[] args) {
        Runnable task = () -> {
            int local = 0;
            local++;
            shared++;
        };
        Thread t1 = new Thread(task);
        Thread t2 = new Thread(task);
        t1.start();
        t2.start();
    }
}
